async createEntities(entities: MemoryEntity[]): Promise<void> {
  for (const entity of entities) {
    // P1.3: O(1) lookup via entityIndex instead of O(n) findIndex
    const existingIndex = this.entityIndex.get(entity.name);

    if (existingIndex !== undefined) {
      // Unindex old entity before replacing
      this.unindexEntity(this.graph.entities[existingIndex]);
      // Update existing entity
      this.graph.entities[existingIndex] = entity;
      // Re-index updated entity
      this.indexEntity(entity, existingIndex);
    } else {
      // Add new entity
      const newIndex = this.graph.entities.length;
      this.graph.entities.push(entity);
      this.indexEntity(entity, newIndex);
    }

    // Initialize episodic metadata if episodic memory
    if (entity.entityType === 'episodic_memory') {
      if (!this.graph.episodicMetadata[entity.name]) {
        this.graph.episodicMetadata[entity.name] = {
          episodeCount: 1,
          lastSummarized: null,
          conversationIds: [],
        };
      }
    }
  }

  await this.persist();
}

/**
 * Create relations
 */
async createRelations(relations: MemoryRelation[]): Promise<void> {
  for (const relation of relations) {
    // Check if relation already exists
    const exists = this.graph.relations.some(
      r =>
        r.from === relation.from &&
        r.to === relation.to &&
        r.relationType === relation.relationType
    );

    if (!exists) {
      this.graph.relations.push(relation);
    }
  }

  await this.persist();
}

